package cn.mop.persistence;
import org.junit.jupiter.api.Test;
import java.util.*;import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.*;
class BackupRunMigrationTest {
 @Test void explicitMigrationRequiresV46AndDoesNotAutoApply()throws Exception{BackupRunSchemaVerifier.resource();var mode=TestSchemaMigration.requestedMode(new String[]{"--apply-backup-run-journal"});assertEquals(TestSchemaMigration.Mode.APPLY_BACKUP_RUN_JOURNAL,mode);assertTrue(TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_DEVICE_COORDINATION_APPLIED));assertFalse(TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.BACKUP_RUN_JOURNAL_APPLIED));assertThrows(IllegalStateException.class,()->TestSchemaMigration.shouldMigrate(mode,TestSchemaMigration.Plan.TICKET_SLA_POLICY_APPLIED));assertFalse(TestSchemaMigration.shouldMigrate(TestSchemaMigration.Mode.READ_ONLY_CHECK,TestSchemaMigration.Plan.BACKUP_RUN_JOURNAL_APPLIED));}
 @Test void exactCheckDefinitionsRejectMissingExtraAndModified(){var expected=BackupRunSchemaVerifier.CHECK_HASHES;assertDoesNotThrow(()->BackupRunSchemaVerifier.requireCheckHashes(expected));var missing=new TreeMap<>(expected);missing.pollFirstEntry();assertThrows(IllegalStateException.class,()->BackupRunSchemaVerifier.requireCheckHashes(missing));var extra=new TreeMap<>(expected);extra.put("unexpected","x");assertThrows(IllegalStateException.class,()->BackupRunSchemaVerifier.requireCheckHashes(extra));var modified=new TreeMap<>(expected);modified.put(modified.firstKey(),"0".repeat(64));assertThrows(IllegalStateException.class,()->BackupRunSchemaVerifier.requireCheckHashes(modified));}
 @Test void journalIsExplicitScopedAndFailClosed()throws Exception{try(var in=getClass().getResourceAsStream("/db/migration/"+BackupRunSchemaVerifier.SCRIPT)){assertNotNull(in);String sql=new String(in.readAllBytes(),StandardCharsets.UTF_8);for(String marker:new String[]{"current_database()<>'mop_test'","PRIMARY KEY(tenant_id,run_id,version)","FOREIGN KEY(tenant_id,asset_id)","FOR UPDATE","transaction_timestamp()","lease_event_version IS NOT NULL","verification_reference IS NOT NULL","CHECK(NOT device_execution_authorized)","GRANT SELECT,INSERT","interval '10 minutes'"})assertTrue(sql.contains(marker),marker);assertFalse(sql.contains("SECURITY DEFINER"));assertFalse(sql.contains("GRANT UPDATE"));assertFalse(sql.contains("GRANT DELETE"));}}
}
